(() => {
  const style=document.createElement('style');style.textContent=`.feature-section{padding:76px 0;background:var(--sand)}.feature-card{max-width:960px;margin:18px auto;background:var(--white);border:1px solid var(--line);border-radius:20px;padding:26px}.feature-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.feature-grid input,.feature-grid select,.feature-grid textarea{font:inherit;padding:12px;border:1px solid var(--line);border-radius:10px;background:var(--white);color:var(--ink)}.feature-grid textarea{grid-column:1/-1;min-height:100px}.feature-grid button{grid-column:1/-1}.review-card{padding:16px;border-left:3px solid var(--accent);margin:12px 0;background:color-mix(in srgb,var(--white) 92%,var(--sand))}.stars{color:#b9862b;letter-spacing:2px}@media(max-width:700px){.feature-grid{grid-template-columns:1fr}}`;document.head.append(style);
  const footer=document.querySelector('footer');const section=document.createElement('section');section.className='feature-section';section.innerHTML=`<div class="shell"><div class="section-head"><div><div class="eyebrow">Planifica tu visita</div><h2>Consulta disponibilidad</h2></div><p>Envía una solicitud para cabañas o salones. El equipo confirmará disponibilidad y condiciones.</p></div><div class="feature-card"><form id="bookingForm" class="feature-grid"><select name="resource_name" required><option value="">Selecciona cabaña o salón</option><option>Salón Darwin</option><option>Salón Orgánico</option><option>Quincho Club House</option><option>Cabaña Boldo</option><option>Casa Arrayán</option><option>Casa de Barro</option><option>Cabaña Ecológica</option></select><input name="guests" type="number" min="1" placeholder="Cantidad de personas"><input name="start_date" type="date" required><input name="end_date" type="date" required><input name="full_name" placeholder="Nombre y apellido" required><input name="phone" type="tel" placeholder="Celular" required><input name="email" type="email" placeholder="Correo (si quieres respuesta por email)"><textarea name="notes" placeholder="Cuéntanos qué estás buscando"></textarea><button class="btn btn-primary">Enviar consulta</button></form><p id="bookingMsg" class="muted"></p></div><div class="section-head" style="margin-top:56px"><div><div class="eyebrow">Experiencia Fundo El Grillo</div><h2>Comparte tu opinión</h2></div><p>Las opiniones se publican una vez revisadas por el equipo.</p></div><div class="feature-card"><form id="reviewForm" class="feature-grid"><input name="full_name" placeholder="Tu nombre" required><select name="rating" required><option value="">Calificación</option><option value="5">★★★★★ · Excelente</option><option value="4">★★★★ · Muy bueno</option><option value="3">★★★ · Bueno</option><option value="2">★★ · Regular</option><option value="1">★ · Malo</option></select><textarea name="comment" placeholder="Cuéntanos tu experiencia" required></textarea><button class="btn btn-primary">Enviar opinión</button></form><p id="reviewMsg" class="muted"></p><div id="reviews"></div></div></div>`;footer.before(section);
  const api=async(u,o)=>{const r=await fetch(u,o);const d=await r.json();if(!r.ok)throw Error(d.error||'No se pudo enviar');return d};document.getElementById('bookingForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/bookings',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});e.target.reset();bookingMsg.textContent='Solicitud enviada. Te contactaremos para confirmar disponibilidad.'}catch(x){bookingMsg.textContent=x.message}};document.getElementById('reviewForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/reviews',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});e.target.reset();reviewMsg.textContent='Gracias. Tu opinión quedará visible tras la revisión del equipo.'}catch(x){reviewMsg.textContent=x.message}};api('/api/reviews').then(d=>reviews.innerHTML=d.reviews.map(r=>`<div class="review-card"><div class="stars">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</div><b>${r.full_name}</b><p>${r.comment}</p></div>`).join('')).catch(()=>{});
})();
